/**
 * Animated figures for the "How Drop7 works" learn page.
 *
 * `RulesScenario` plays back frames that were generated by the repository's
 * TypeScript engine (web/scripts/generate-rules-scenarios.ts →
 * web/content/learn/rules-scenarios.json), so every board shown is real engine
 * output. The remaining figures are purpose-built diagrams for mechanics that
 * are easier to see than to play (a disc falling, counting a run, the rise
 * clock, the score curve, what the player sees).
 *
 * All figures are server components: SVG + SMIL + CSS. Every animation has a
 * static equivalent on the page, and CSS motion stops under
 * prefers-reduced-motion (globals.css).
 */

import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { CellGlyph, parseBoard } from "./Board";
import { MiniBoard } from "./Engine";

const INK = "#fafafa";
const INK_2 = "#a1a1aa";
const INK_3 = "#71717a";
const GRID = "#27272a";
const BLUE = "#3987e5";
const AQUA = "#199e70";
const ORANGE = "#d95926";
const ACCENT = "#facc15";
const FONT = "system-ui, -apple-system, 'Segoe UI', sans-serif";

/* ------------------------------------------------------------------------ */
/* Scenario data                                                             */
/* ------------------------------------------------------------------------ */

interface ScenarioFrame {
  kind: "start" | "drop" | "wave" | "covers" | "gravity" | "rise" | "end";
  board: string;
  indexes: number[];
  chainDepth: number | null;
}

interface Scenario {
  initial: { board: string; nextDisc: number; movesRemaining: number; level: number };
  column: number;
  frames: ScenarioFrame[];
  waves: { depth: number; cleared: number; revealed: number; points: number }[];
  scoreDelta: number;
  clearedBoard: boolean;
  levelAdvanced: boolean;
  gameOver: boolean;
  final: { board: string; movesRemaining: number; level: number; score: number };
}

function loadScenarios(): Record<string, Scenario> | null {
  const path = join(process.cwd(), "content", "learn", "rules-scenarios.json");
  if (!existsSync(path)) return null;
  return JSON.parse(readFileSync(path, "utf8")) as Record<string, Scenario>;
}

function fmt(n: number): string {
  return n.toLocaleString("en-US");
}

function frameLabel(frame: ScenarioFrame, scenario: Scenario): string {
  switch (frame.kind) {
    case "start":
      return "Before the move";
    case "drop":
      return "The disc drops to the lowest empty cell";
    case "wave": {
      const wave = scenario.waves.find((w) => w.depth === frame.chainDepth);
      const n = frame.indexes.length;
      return `Wave ${frame.chainDepth}: ${n} disc${n === 1 ? "" : "s"} match and clear${
        wave ? ` (+${fmt(wave.points)})` : ""
      }`;
    }
    case "covers":
      return frame.indexes.length > 0
        ? "Cleared — and neighbouring gray discs take hits"
        : "Cleared";
    case "gravity":
      return "Gravity: everything above falls";
    case "rise":
      return "Fifth drop: the board rises (+17,000)";
    case "end":
      if (scenario.gameOver) return "Game over";
      if (scenario.clearedBoard) return "Board cleared (+70,000)";
      return "Settled — ready for the next disc";
  }
}

function scoreThrough(frameIndex: number, scenario: Scenario): number {
  let score = 0;
  for (let i = 0; i <= frameIndex; i += 1) {
    const f = scenario.frames[i];
    if (f.kind === "wave") {
      score += scenario.waves.find((w) => w.depth === f.chainDepth)?.points ?? 0;
    }
    if (f.kind === "rise") score += 17_000;
    if (f.kind === "end" && scenario.clearedBoard) score += 70_000;
  }
  return score;
}

function movesLeftAt(frameIndex: number, scenario: Scenario): number {
  const f = scenario.frames[frameIndex];
  if (f.kind === "start") return scenario.initial.movesRemaining;
  const risen = scenario.frames.slice(0, frameIndex + 1).some((x) => x.kind === "rise");
  if (risen) return 5;
  return scenario.initial.movesRemaining - 1;
}

/* ------------------------------------------------------------------------ */
/* RulesScenario — engine-generated playback                                 */
/* ------------------------------------------------------------------------ */

export function RulesScenario({
  id,
  notes = [],
  secondsPerFrame = 1.7,
  caption,
}: {
  id: string;
  /** Optional note per frame, in frame order. */
  notes?: string[];
  secondsPerFrame?: number;
  caption?: string;
}) {
  const scenarios = loadScenarios();
  const scenario = scenarios?.[id];
  if (!scenario) {
    return (
      <div className="engine-fig" style={{ color: INK_3, fontSize: 13 }}>
        Scenario <code>{id}</code> is not available in this checkout. Run{" "}
        <code>npm run rules:scenarios</code> inside <code>web/</code> to regenerate
        <code> content/learn/rules-scenarios.json</code>.
      </div>
    );
  }
  const frames = scenario.frames;
  const n = frames.length;
  const dur = n * secondsPerFrame;
  const s = 38;
  const W = 7 * s + 430;
  const H = 7 * s + 12;
  const thumb = 13;
  const panelX = 7 * s + 22;

  return (
    <figure className="engine-fig">
      <div className="engine-motion">
        <svg
          viewBox={`0 -${s + 6} ${W} ${H + s + 6}`}
          role="img"
          aria-label="Animated Drop7 move, generated by the rules engine"
          style={{ maxWidth: 700 }}
        >
          {frames.map((frame, i) => {
            const keyTimes =
              i === 0
                ? `0;${(1 / n).toFixed(4)}`
                : i === n - 1
                  ? `0;${(i / n).toFixed(4)}`
                  : `0;${(i / n).toFixed(4)};${((i + 1) / n).toFixed(4)}`;
            const values = i === 0 ? "1;0" : i === n - 1 ? "0;1" : "0;1;0";
            const isDrop = frame.kind === "drop";
            const outline = frame.kind === "start" ? [] : frame.indexes;
            const note = notes[i];
            return (
              <g key={i} opacity={i === 0 ? 1 : 0}>
                <animate
                  attributeName="opacity"
                  calcMode="discrete"
                  values={values}
                  keyTimes={keyTimes}
                  dur={`${dur}s`}
                  repeatCount="indefinite"
                />
                {/* column marker for the move */}
                {(frame.kind === "start" || isDrop) && (
                  <g>
                    <rect
                      x={scenario.column * s}
                      y={0}
                      width={s}
                      height={7 * s}
                      rx={6}
                      fill="rgba(250,204,21,0.08)"
                    />
                  </g>
                )}
                <MiniBoard cells={frame.board} s={s} highlight={outline} />
                {/* the incoming disc, shown above the board before it is placed */}
                {frame.kind === "start" && (
                  <g transform={`translate(${scenario.column * s} ${-s - 4})`}>
                    <CellGlyph cell={scenario.initial.nextDisc} x={0} y={0} s={s} />
                  </g>
                )}

                {/* side panel */}
                <text x={panelX} y={20} fontSize={11} fontFamily={FONT} fill={INK_3}>
                  step {i + 1} of {n}
                </text>
                <text
                  x={panelX}
                  y={44}
                  fontSize={14.5}
                  fontFamily={FONT}
                  fontWeight={700}
                  fill={INK}
                >
                  {frameLabel(frame, scenario)}
                </text>
                {note &&
                  wrap(note, 54).map((line, li) => (
                    <text
                      key={li}
                      x={panelX}
                      y={68 + li * 16}
                      fontSize={11.5}
                      fontFamily={FONT}
                      fill={INK_2}
                    >
                      {line}
                    </text>
                  ))}

                {/* HUD */}
                <g transform={`translate(${panelX} ${H - 58})`}>
                  <Hud
                    nextDisc={
                      frame.kind === "start" || frame.kind === "drop"
                        ? null
                        : scenario.gameOver
                          ? null
                          : 0
                    }
                    movesLeft={movesLeftAt(i, scenario)}
                    score={scoreThrough(i, scenario)}
                    gameOver={frame.kind === "end" && scenario.gameOver}
                  />
                </g>
                {/* progress ticks */}
                {frames.map((_, t) => (
                  <rect
                    key={t}
                    x={panelX + t * 13}
                    y={H - 8}
                    width={9}
                    height={4}
                    rx={2}
                    fill={t === i ? BLUE : GRID}
                  />
                ))}
              </g>
            );
          })}
        </svg>
      </div>

      {/* static filmstrip */}
      <div style={{ display: "flex", flexWrap: "wrap", gap: 10, marginTop: 10 }}>
        {frames.map((frame, i) => (
          <div key={i} style={{ width: 7 * thumb + 4 }}>
            <svg viewBox={`0 0 ${7 * thumb} ${7 * thumb}`} width={7 * thumb} height={7 * thumb}>
              <MiniBoard
                cells={frame.board}
                s={thumb}
                highlight={frame.kind === "start" ? [] : frame.indexes}
              />
            </svg>
            <div style={{ fontSize: 10, color: INK_3, lineHeight: 1.3, marginTop: 2 }}>
              {i + 1}. {frameLabel(frame, scenario)}
            </div>
          </div>
        ))}
      </div>

      <div className="engine-caption" style={{ color: INK_2 }}>
        <strong style={{ color: INK }}>Result:</strong> score +{fmt(scenario.scoreDelta)}
        {scenario.waves.length > 0 && (
          <>
            {" · "}
            {scenario.waves.length} wave{scenario.waves.length === 1 ? "" : "s"} (
            {scenario.waves
              .map((w) => `wave ${w.depth}: ${w.cleared} × ${fmt(w.points / w.cleared)}`)
              .join(", ")}
            )
          </>
        )}
        {scenario.levelAdvanced && " · the board rose and the rise clock reset to 5"}
        {scenario.clearedBoard && " · board-clear bonus included"}
        {scenario.gameOver && " · the game is over"}
      </div>
      {caption && <figcaption>{caption}</figcaption>}
    </figure>
  );
}

function wrap(text: string, width: number): string[] {
  const words = text.split(" ");
  const lines: string[] = [];
  let line = "";
  for (const word of words) {
    if ((line + " " + word).trim().length > width) {
      lines.push(line.trim());
      line = word;
    } else {
      line = line + " " + word;
    }
  }
  if (line.trim()) lines.push(line.trim());
  return lines;
}

function Hud({
  nextDisc,
  movesLeft,
  score,
  gameOver,
}: {
  nextDisc: number | null;
  movesLeft: number;
  score: number;
  gameOver: boolean;
}) {
  void nextDisc;
  return (
    <g>
      <text x={0} y={10} fontSize={10} fontFamily={FONT} fill={INK_3}>
        drops until rise
      </text>
      {Array.from({ length: 5 }, (_, i) => (
        <rect
          key={i}
          x={i * 14}
          y={16}
          width={10}
          height={10}
          rx={3}
          fill={i < movesLeft ? AQUA : "#1f1f23"}
          stroke={GRID}
        />
      ))}
      <text x={150} y={10} fontSize={10} fontFamily={FONT} fill={INK_3}>
        points this move
      </text>
      <text x={150} y={27} fontSize={14} fontFamily={FONT} fontWeight={700} fill={INK}>
        {gameOver ? "game over" : `+${fmt(score)}`}
      </text>
    </g>
  );
}

/* ------------------------------------------------------------------------ */
/* DropPhysics — a disc falls until it rests on the highest occupied cell    */
/* ------------------------------------------------------------------------ */

export function DropPhysics({ caption }: { caption?: string }) {
  const s = 40;
  const board = "0000000000000000000000000000000000000000000004006";
  const column = 3; // lands on row 5 (row 6 holds a 4)
  const landingRow = 5;
  const W = 7 * s + 260;
  const H = 7 * s + s;
  return (
    <figure className="engine-fig">
      <svg viewBox={`0 -${s} ${W} ${H}`} role="img" aria-label="A disc dropping into a column">
        <rect x={column * s} y={-s} width={s} height={8 * s} rx={6} fill="rgba(57,135,229,0.08)" />
        <MiniBoard cells={board} s={s} />
        <g className="engine-motion">
          <g transform={`translate(${column * s} ${-s})`}>
            <animateTransform
              attributeName="transform"
              type="translate"
              values={`${column * s} ${-s}; ${column * s} ${-s}; ${column * s} ${landingRow * s}; ${column * s} ${landingRow * s}`}
              keyTimes="0;0.25;0.55;1"
              calcMode="spline"
              keySplines="0 0 1 1; 0.4 0 1 1; 0 0 1 1"
              dur="3s"
              repeatCount="indefinite"
            />
            <CellGlyph cell={5} x={0} y={0} s={s} />
          </g>
        </g>
        {/* static ghost at landing spot for reduced motion */}
        <g opacity={0.35}>
          <CellGlyph cell={5} x={column * s} y={landingRow * s} s={s} />
        </g>
        <g transform={`translate(${7 * s + 20} 0)`}>
          <text y={14} fontSize={13} fontFamily={FONT} fontWeight={700} fill={INK}>
            You choose a column, not a cell
          </text>
          {wrap(
            "The disc slides down until it rests on the highest occupied cell of that column — here the 4 in the bottom row. You cannot place a disc anywhere else, and you cannot skip a turn.",
            38,
          ).map((line, i) => (
            <text key={i} y={36 + i * 16} fontSize={11.5} fontFamily={FONT} fill={INK_2}>
              {line}
            </text>
          ))}
        </g>
      </svg>
      {caption && <figcaption>{caption}</figcaption>}
    </figure>
  );
}

/* ------------------------------------------------------------------------ */
/* RunCounter — count the contiguous run through a disc, compare to its value */
/* ------------------------------------------------------------------------ */

export function RunCounter({
  row,
  focus,
  caption,
}: {
  /** Seven cells in serializeBoard encoding. */
  row: string;
  /** Column (0–6) of the disc whose run is counted. */
  focus: number;
  caption?: string;
}) {
  const cells = parseBoard(row);
  // contiguous occupied run through `focus`
  let start = focus;
  while (start > 0 && cells[start - 1] !== 0) start -= 1;
  let end = focus;
  while (end < 6 && cells[end + 1] !== 0) end += 1;
  const run = Array.from({ length: end - start + 1 }, (_, i) => start + i);
  const value = cells[focus];
  const matches = run.length === value;
  const s = 44;
  const W = 7 * s + 250;
  const H = s + 70;
  const stepDur = 0.6;
  const total = run.length * stepDur + 1.8;
  return (
    <figure className="engine-fig">
      <svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label="Counting a run of discs">
        <rect width={7 * s} height={s} rx={6} fill="#030712" />
        {cells.map((cell, i) => (
          <CellGlyph key={i} cell={cell} x={i * s} y={0} s={s} />
        ))}
        {/* focus outline */}
        <rect
          x={focus * s + 2}
          y={2}
          width={s - 4}
          height={s - 4}
          rx={6}
          fill="none"
          stroke={ACCENT}
          strokeWidth={3}
        />
        {/* animated count badges */}
        <g className="engine-motion">
          {run.map((col, k) => {
            const t0 = ((k * stepDur) / total).toFixed(4);
            const t1 = (((k + 1) * stepDur) / total - 0.0001).toFixed(4);
            return (
              <g key={col} opacity={0}>
                <animate
                  attributeName="opacity"
                  calcMode="discrete"
                  values={`0;1;1;0`}
                  keyTimes={`0;${t0};${(total - 0.01) / total};1`}
                  dur={`${total}s`}
                  repeatCount="indefinite"
                />
                <rect
                  x={col * s + 2}
                  y={s + 8}
                  width={s - 4}
                  height={20}
                  rx={5}
                  fill={matches ? AQUA : ORANGE}
                >
                  <animate
                    attributeName="fill"
                    calcMode="discrete"
                    values={`${BLUE};${matches ? AQUA : ORANGE}`}
                    keyTimes={`0;${t1}`}
                    dur={`${total}s`}
                    repeatCount="indefinite"
                  />
                </rect>
                <text
                  x={col * s + s / 2}
                  y={s + 18.5}
                  textAnchor="middle"
                  dominantBaseline="central"
                  fontSize={12}
                  fontFamily={FONT}
                  fontWeight={700}
                  fill="#ffffff"
                >
                  {k + 1}
                </text>
              </g>
            );
          })}
        </g>
        {/* static count strip underneath for reduced motion */}
        <g>
          {run.map((col, k) => (
            <text
              key={col}
              x={col * s + s / 2}
              y={s + 46}
              textAnchor="middle"
              fontSize={10}
              fontFamily={FONT}
              fill={INK_3}
            >
              {k + 1}
            </text>
          ))}
        </g>
        <g transform={`translate(${7 * s + 18} 0)`}>
          <text y={14} fontSize={12.5} fontFamily={FONT} fontWeight={700} fill={INK}>
            run of {run.length} through a {value}
          </text>
          <text y={34} fontSize={12} fontFamily={FONT} fill={matches ? AQUA : ORANGE} fontWeight={700}>
            {matches ? `${run.length} = ${value} → it clears` : `${run.length} ≠ ${value} → it stays`}
          </text>
          {wrap(
            matches
              ? "Every disc in the board whose row-run or column-run equals its number clears in the same wave."
              : run.some((c) => cells[c] === 8 || cells[c] === 9)
                ? "Gray discs count toward the run length even though they have no number to compare."
                : "The match must be exact. A run longer than the number does nothing, and every other disc in the run counts toward its length.",
            36,
          ).map((line, i) => (
            <text key={i} y={54 + i * 15} fontSize={11} fontFamily={FONT} fill={INK_2}>
              {line}
            </text>
          ))}
        </g>
      </svg>
      {caption && <figcaption>{caption}</figcaption>}
    </figure>
  );
}

/* ------------------------------------------------------------------------ */
/* RiseClock — five drops, then the board rises                              */
/* ------------------------------------------------------------------------ */

export function RiseClock({ caption }: { caption?: string }) {
  const W = 640;
  const H = 128;
  const steps = 6; // 5 drops then rise
  const dur = 7.2;
  return (
    <figure className="engine-fig">
      <svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label="The rise clock counts down five drops">
        {Array.from({ length: steps }, (_, i) => {
          const x = 20 + i * 100;
          const isRise = i === 5;
          const t0 = (i / steps).toFixed(3);
          const t1 = ((i + 1) / steps).toFixed(3);
          return (
            <g key={i} transform={`translate(${x} 0)`}>
              <rect
                width={84}
                height={72}
                rx={10}
                fill={isRise ? "rgba(217,89,38,0.15)" : "#18181b"}
                stroke={isRise ? ORANGE : GRID}
              />
              <text x={42} y={20} textAnchor="middle" fontSize={11} fontFamily={FONT} fill={INK_3}>
                {isRise ? "then" : `drop ${i + 1}`}
              </text>
              {!isRise ? (
                <g transform="translate(12 30)">
                  {Array.from({ length: 5 }, (_, p) => (
                    <rect
                      key={p}
                      x={p * 12.5}
                      y={0}
                      width={10}
                      height={10}
                      rx={3}
                      fill={p < 5 - (i + 1) ? AQUA : "#1f1f23"}
                      stroke={GRID}
                    />
                  ))}
                  <text x={30} y={30} textAnchor="middle" fontSize={10} fontFamily={FONT} fill={INK_2}>
                    {5 - (i + 1)} left
                  </text>
                </g>
              ) : (
                <g>
                  <text x={42} y={44} textAnchor="middle" fontSize={14} fontFamily={FONT} fontWeight={700} fill={INK}>
                    ▲ rise
                  </text>
                  <text x={42} y={60} textAnchor="middle" fontSize={10} fontFamily={FONT} fill={INK_2}>
                    +17,000
                  </text>
                </g>
              )}
              <g className="engine-motion">
                <rect width={84} height={72} rx={10} fill="none" stroke={ACCENT} strokeWidth={2.5} opacity={0}>
                  <animate
                    attributeName="opacity"
                    calcMode="discrete"
                    values="0;1;0"
                    keyTimes={`0;${t0};${t1}`}
                    dur={`${dur}s`}
                    repeatCount="indefinite"
                  />
                </rect>
              </g>
            </g>
          );
        })}
        <text x={20} y={98} fontSize={11} fontFamily={FONT} fill={INK_3}>
          The clock resets to 5 after every rise. A chain that is still running when the rise
        </text>
        <text x={20} y={113} fontSize={11} fontFamily={FONT} fill={INK_3}>
          happens keeps counting its wave depth instead of starting again at wave 1.
        </text>
      </svg>
      {caption && <figcaption>{caption}</figcaption>}
    </figure>
  );
}

/* ------------------------------------------------------------------------ */
/* ScoreCurve — points per cleared disc by chain wave                         */
/* ------------------------------------------------------------------------ */

export function ScoreCurve({ maxDepth = 8, caption }: { maxDepth?: number; caption?: string }) {
  const rows = Array.from({ length: maxDepth }, (_, i) => {
    const d = i + 1;
    return { depth: d, points: Math.floor(7 * Math.pow(d, 2.5)) };
  });
  const labelW = 90;
  const plotW = 420;
  const rowH = 24;
  const barH = 14;
  const max = rows[rows.length - 1].points;
  const W = labelW + plotW + 80;
  const H = rows.length * rowH + 30;
  const xOf = (v: number) => labelW + (v / max) * plotW;
  return (
    <figure className="engine-fig">
      <div style={{ fontSize: 13, color: INK, fontWeight: 600 }}>
        Points per cleared disc, by chain wave — floor(7 × d^2.5)
      </div>
      <svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label="Points per disc by chain wave" style={{ marginTop: 6 }}>
        {[0, 400, 800, 1200].map((t) => (
          <g key={t}>
            <path d={`M${xOf(t)},4 V${H - 20}`} stroke={GRID} strokeWidth={1} />
            <text x={xOf(t)} y={H - 6} textAnchor="middle" fontSize={10} fontFamily={FONT} fill={INK_3}>
              {fmt(t)}
            </text>
          </g>
        ))}
        {rows.map((row, i) => {
          const y = 10 + i * rowH;
          const w = xOf(row.points) - labelW;
          const r = Math.min(4, w / 2);
          return (
            <g key={row.depth}>
              <title>{`wave ${row.depth}: ${fmt(row.points)} points per disc`}</title>
              <text x={labelW - 10} y={y + barH / 2} textAnchor="end" dominantBaseline="central" fontSize={11.5} fontFamily={FONT} fill={INK_2}>
                wave {row.depth}
              </text>
              <path
                d={`M${labelW},${y} h${w - r} a${r},${r} 0 0 1 ${r},${r} v${barH - 2 * r} a${r},${r} 0 0 1 ${-r},${r} h${-(w - r)} z`}
                fill={BLUE}
              />
              <text x={labelW + w + 6} y={y + barH / 2} dominantBaseline="central" fontSize={11.5} fontFamily={FONT} fontWeight={700} fill={INK}>
                {fmt(row.points)}
              </text>
            </g>
          );
        })}
      </svg>
      <details className="engine-table">
        <summary>table view</summary>
        <table>
          <thead>
            <tr>
              <th>chain wave</th>
              <th>points per disc</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => (
              <tr key={row.depth}>
                <td>{row.depth}</td>
                <td>{fmt(row.points)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </details>
      {caption && <figcaption>{caption}</figcaption>}
    </figure>
  );
}

/* ------------------------------------------------------------------------ */
/* PlayerView — what the player (and a legal policy) can see                 */
/* ------------------------------------------------------------------------ */

export function PlayerView({ caption }: { caption?: string }) {
  const s = 34;
  const board = "0000000000000000000000000000000200000053000889854";
  const cells = parseBoard(board);
  const W = 7 * s + 330;
  const H = 7 * s + 10;
  const items = [
    { label: "the board", detail: "every visible disc, including which grays are cracked", ok: true },
    { label: "the next disc", detail: "shown before you choose a column", ok: true },
    { label: "drops until the rise", detail: "the five-step clock", ok: true },
    { label: "hidden gray values", detail: "fixed when the row appeared, unknown until revealed", ok: false },
    { label: "future discs", detail: "the random sequence is not knowable", ok: false },
  ];
  return (
    <figure className="engine-fig">
      <svg viewBox={`0 -${s + 16} ${W} ${H + s + 16}`} role="img" aria-label="What the player sees">
        <text x={0} y={-s + 6} fontSize={11} fontFamily={FONT} fill={INK_3}>
          next
        </text>
        <g transform={`translate(34 ${-s - 4})`}>
          <CellGlyph cell={6} x={0} y={0} s={s} />
        </g>
        <g transform={`translate(${7 * s - 74} ${-s + 2})`}>
          {Array.from({ length: 5 }, (_, p) => (
            <rect key={p} x={p * 14} y={4} width={10} height={10} rx={3} fill={p < 3 ? AQUA : "#1f1f23"} stroke={GRID} />
          ))}
          <text x={0} y={-2} fontSize={10} fontFamily={FONT} fill={INK_3}>
            3 drops to rise
          </text>
        </g>
        <MiniBoard cells={cells} s={s} />
        <g transform={`translate(${7 * s + 20} 0)`}>
          {items.map((item, i) => (
            <g key={item.label} transform={`translate(0 ${i * 46})`}>
              <circle cx={8} cy={10} r={7} fill={item.ok ? "rgba(25,158,112,0.2)" : "rgba(217,89,38,0.2)"} stroke={item.ok ? AQUA : ORANGE} />
              <text x={8} y={10.5} textAnchor="middle" dominantBaseline="central" fontSize={9} fontFamily={FONT} fontWeight={700} fill={item.ok ? AQUA : ORANGE}>
                {item.ok ? "✓" : "✕"}
              </text>
              <text x={22} y={14} fontSize={12} fontFamily={FONT} fontWeight={700} fill={INK}>
                {item.label}
              </text>
              <text x={22} y={30} fontSize={10.5} fontFamily={FONT} fill={INK_2}>
                {item.detail}
              </text>
            </g>
          ))}
        </g>
      </svg>
      {caption && <figcaption>{caption}</figcaption>}
    </figure>
  );
}

/* ------------------------------------------------------------------------ */
/* LegalColumns — a full column cannot take a disc                           */
/* ------------------------------------------------------------------------ */

export function LegalColumns({ caption }: { caption?: string }) {
  const s = 34;
  // column 2 is full (top cell occupied); others have room
  const board = "0050000005000000500000050000005000000500000350000";
  const cells = parseBoard(board);
  const legal = Array.from({ length: 7 }, (_, c) => cells[c] === 0);
  const W = 7 * s + 330;
  const H = 7 * s + 40;
  return (
    <figure className="engine-fig">
      <svg viewBox={`0 -30 ${W} ${H}`} role="img" aria-label="Legal and illegal columns">
        {legal.map((ok, c) => (
          <g key={c} transform={`translate(${c * s} -26)`}>
            <rect width={s - 4} height={18} x={2} rx={4} fill={ok ? "rgba(25,158,112,0.2)" : "rgba(217,89,38,0.25)"} stroke={ok ? AQUA : ORANGE} />
            <text x={s / 2} y={9.5} textAnchor="middle" dominantBaseline="central" fontSize={10} fontFamily={FONT} fontWeight={700} fill={ok ? AQUA : ORANGE}>
              {ok ? "ok" : "full"}
            </text>
          </g>
        ))}
        <MiniBoard cells={cells} s={s} />
        <g transform={`translate(${7 * s + 20} 0)`}>
          <text y={14} fontSize={12.5} fontFamily={FONT} fontWeight={700} fill={INK}>
            Legal while the top cell is empty
          </text>
          {wrap(
            "Column 2 is stacked to the top, so it cannot accept a disc. If every column is full, the game ends immediately. A full column also blocks the next rise: the board cannot shift up into an occupied top row.",
            40,
          ).map((line, i) => (
            <text key={i} y={36 + i * 15} fontSize={11.5} fontFamily={FONT} fill={INK_2}>
              {line}
            </text>
          ))}
        </g>
      </svg>
      {caption && <figcaption>{caption}</figcaption>}
    </figure>
  );
}

/* ------------------------------------------------------------------------ */
/* DiscLegend — the three kinds of cell                                      */
/* ------------------------------------------------------------------------ */

export function DiscLegend() {
  const s = 36;
  const entries = [
    { cell: 4, title: "numbered disc (1–7)", text: "clears when its row-run or column-run is exactly its number" },
    { cell: 8, title: "solid gray disc", text: "hides a number; counts as occupied; needs two hits to open" },
    { cell: 9, title: "cracked gray disc", text: "has taken one hit; one more reveals the number underneath" },
    { cell: 0, title: "empty cell", text: "discs fall through it; a run stops at it" },
  ];
  return (
    <div className="engine-fig" style={{ display: "grid", gap: 10, gridTemplateColumns: "repeat(auto-fit, minmax(240px, 1fr))" }}>
      {entries.map((e) => (
        <div key={e.title} style={{ display: "flex", gap: 12, alignItems: "center" }}>
          <svg width={s} height={s} viewBox={`0 0 ${s} ${s}`} aria-hidden="true">
            <rect width={s} height={s} rx={6} fill="#030712" />
            <CellGlyph cell={e.cell} x={0} y={0} s={s} />
          </svg>
          <div>
            <div style={{ fontSize: 12.5, fontWeight: 700, color: INK }}>{e.title}</div>
            <div style={{ fontSize: 11.5, color: INK_2, lineHeight: 1.4 }}>{e.text}</div>
          </div>
        </div>
      ))}
    </div>
  );
}

